      "chapter_id": 3,
      "title": "Mutual Damage",
      "goal": "Form a reluctant alliance with a local familiar/clerk and another trapped arrival based on shared incentives rather than trust.",
      "chapter_role": "alliance",
      "stakes_shift": "From solo survival to managing the liabilities and benefits of a party.",
      "bridge": {
        "from_prev": "Rhea's economic exploit gives her leverage to recruit.",
        "to_next": "The new party's combined skills allow them to analyze the quest board's underlying math."
