        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 6
      }
    },
    {
      "chapter_id": 4,
      "title": "The Skim",
      "goal": "Investigate the local quest payouts and discover that the Ledger's standard rewards are being actively siphoned by a local administrator.",
      "chapter_role": "investigation",
      "stakes_shift": "From surviving the environment to recognizing the environment is a managed fraud scheme.",
      "bridge": {
        "from_prev": "The party notices discrepancies in their XP and loot yields.",
        "to_next": "Armed with proof of the skim, Rhea decides to weaponize the system's own audit rules."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "slow_burn",
        "expected_scene_count": 7
      }
    },
    {
      "chapter_id": 5,
      "title": "Auditing Reality",
      "goal": "Execute a mid-level exploit that forces the system to refund stolen XP/loot, drawing the ire of the local frontier overseer.",
      "chapter_role": "hinge",
      "stakes_shift": "From passive victim of the skim to active threat to the local power structure.",
      "bridge": {
        "from_prev": "Rhea files a metaphysical grievance through the Ledger.",
        "to_next": "The overseer retaliates using administrative debt mechanics."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 7
      }
    },
    {
      "chapter_id": 6,
      "title": "Administrative Cruelty",
      "goal": "Survive the overseer's targeted harassment, which uses debt logic and rigged encounters to try and bankrupt Rhea's HP and resources.",
      "chapter_role": "pressure",
      "stakes_shift": "From flying under the radar to fighting a defensive war against the system's bureaucracy.",
      "bridge": {
        "from_prev": "The overseer flags Rhea's party for 'audit compliance' encounters.",
        "to_next": "Pushed to the brink, Rhea prepares a counter-audit to crash the local node."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 6
      }
    },
    {
      "chapter_id": 7,
      "title": "The Mercy Cache",
      "goal": "Breach the local administrative hub, expose the systemic leak, and defeat the overseer by turning his own predatory contracts against him.",
      "chapter_role": "climax",
      "stakes_shift": "From desperate defense to dismantling the local frontier authority.",
      "bridge": {
        "from_prev": "Rhea corners the overseer in his own administrative sanctum.",
        "to_next": "With the local node broken, the wider Ledger system takes notice."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 7
      }
